const fs = require('fs');
let source = fs.readFileSync('src/session.js', 'utf8')
  .replace('export class DialogResource', 'class DialogResource')
  .replace('export class WorkspaceJob', 'class WorkspaceJob')
  .replace('export function createResource', 'function createResource');
const { DialogResource } = new Function(`${source}\nreturn { DialogResource };`)();
const flush = () => new Promise(resolve => setImmediate(resolve));
function deferred() { let resolve; return { promise: new Promise(r => { resolve = r; }), resolve }; }
function hostWithChecks() {
  const requests = [], scheduled = [], cancelled = [], publications = [];
  return {
    requests, scheduled, cancelled, publications,
    host: {
      check(token) { const request = deferred(); requests.push({ token, ...request }); return request.promise; },
      schedule(callback) { scheduled.push(callback); return scheduled.length - 1; },
      cancel(id) { cancelled.push(id); },
      publish(state) { publications.push(state); }
    }
  };
}
(async () => {
  const one = hostWithChecks();
  const dialog = new DialogResource(one.host, 'package-1');
  dialog.start();
  one.requests[0].resolve(false); await flush();
  if (one.scheduled.length !== 1 || dialog.snapshot().completed.length) throw Error('initial pending did not defer a retry');
  one.scheduled[0](); one.requests[1].resolve(false); await flush();
  if (one.scheduled.length !== 2 || dialog.snapshot().completed.length) throw Error('repeated pending did not defer a retry');
  one.scheduled[1](); one.requests[2].resolve(true); await flush();
  let state = dialog.snapshot();
  if (state.completed.join() !== 'package-1' || state.loading || state.retryScheduled || one.scheduled.length !== 2) throw Error('ready did not deliver and end active retrying');

  const two = hostWithChecks();
  const closed = new DialogResource(two.host, 'package-2');
  closed.start(); two.requests[0].resolve(false); await flush();
  closed.close(); two.scheduled[0](); await flush();
  if (two.requests.length !== 1 || two.cancelled.join() !== '0' || closed.snapshot().completed.length) throw Error('close did not invalidate queued retry');

  const three = hostWithChecks();
  const reopened = new DialogResource(three.host, 'old');
  reopened.start(); reopened.reopen('new');
  three.requests[1].resolve(true); await flush();
  three.requests[0].resolve(true); await flush();
  state = reopened.snapshot();
  if (state.completed.join() !== 'new' || state.token !== 'new') throw Error('reopen accepted an obsolete response');
  console.log('session DialogResource lifecycle checks: passed');
})().catch(error => { console.error(error); process.exitCode = 1; });
